import base64
import glob
import io
import os
import subprocess
import sys
import time
import zipfile

subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "python-chess"])

PKG = "/kaggle/working/pkg"
os.makedirs(PKG, exist_ok=True)
with zipfile.ZipFile(io.BytesIO(base64.b64decode(''))) as z:
    z.extractall(PKG)
sys.path.insert(0, PKG)

import numpy as np
import torch
import torch.nn.functional as F

from eightchess_nnue import format as nnue_format
from eightchess_nnue.encoder import load_encoded
from eightchess_nnue.export import quantize_weights
from eightchess_nnue.model import EightChessNNUE, wdl_from_cp
from eightchess_nnue.train import EncodedDataset

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"device={device} torch={torch.__version__}")

npz_candidates = glob.glob("/kaggle/input/**/train_368k.npz", recursive=True)
net_candidates = glob.glob("/kaggle/input/**/eightchess_tuned_master.nnue", recursive=True)
print("npz:", npz_candidates, flush=True)
print("net:", net_candidates, flush=True)
NPZ = npz_candidates[0]
NET = net_candidates[0]

raw = load_encoded(NPZ)
n = int(raw["bucket"].shape[0])
rng = np.random.default_rng(20261020)
perm = rng.permutation(n)
split = int(n * 0.95)
train_idx, val_idx = perm[:split], perm[split:]


def subset(data, indices):
    out = {}
    for stream in ("piece_stm", "threat_stm", "piece_opp", "threat_opp"):
        idx = data[f"{stream}_indices"]
        off = data[f"{stream}_offsets"]
        starts = off[indices]
        ends = off[indices + 1]
        lengths = ends - starts
        new_off = np.zeros(len(indices) + 1, dtype=np.int64)
        np.cumsum(lengths, out=new_off[1:])
        new_idx = np.empty(int(lengths.sum()), dtype=np.int32)
        pos = 0
        for st, ln in zip(starts, lengths):
            ln = int(ln)
            new_idx[pos : pos + ln] = idx[st : st + ln]
            pos += ln
        out[f"{stream}_indices"] = new_idx
        out[f"{stream}_offsets"] = new_off
    out["bucket"] = data["bucket"][indices]
    out["target"] = data["target"][indices]
    return out


train_ds = EncodedDataset(subset(raw, train_idx), device)
val_ds = EncodedDataset(subset(raw, val_idx), device)
print(f"train={train_ds.size:,} val={val_ds.size:,}")

model = EightChessNNUE.load_network_file(NET).to(device)
optimizer = torch.optim.AdamW(model.parameters(), lr=3e-4, weight_decay=1e-5)

epochs = 40
batch_size = 4096
steps = (train_ds.size // batch_size + 1) * epochs
scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(optimizer, T_max=steps, eta_min=1e-5)

best_val = float("inf")
best_path = "/kaggle/working/eightchess_d9_master.nnue"


def forward(batch):
    return model(
        batch["piece_stm_indices"],
        batch["piece_stm_offsets"],
        batch["threat_stm_indices"],
        batch["threat_stm_offsets"],
        batch["piece_opp_indices"],
        batch["piece_opp_offsets"],
        batch["threat_opp_indices"],
        batch["threat_opp_offsets"],
        batch["buckets"],
    )


for epoch in range(1, epochs + 1):
    model.train()
    t0 = time.time()
    order = rng.permutation(train_ds.size)
    total = 0.0
    batches = 0

    for start in range(0, train_ds.size, batch_size):
        batch = train_ds.get_batch(order[start : start + batch_size])
        optimizer.zero_grad(set_to_none=True)
        pred = wdl_from_cp(forward(batch) * 380.0, 410.0)
        loss = F.binary_cross_entropy(pred, batch["targets"])
        loss.backward()
        optimizer.step()
        scheduler.step()
        total += float(loss.item())
        batches += 1

    model.eval()
    val_total = 0.0
    val_batches = 0
    with torch.no_grad():
        for start in range(0, val_ds.size, batch_size):
            batch = val_ds.get_batch(np.arange(start, min(start + batch_size, val_ds.size)))
            pred = wdl_from_cp(forward(batch) * 380.0, 410.0)
            val_total += float(F.binary_cross_entropy(pred, batch["targets"]).item())
            val_batches += 1
    val_loss = val_total / max(val_batches, 1)
    train_loss = total / max(batches, 1)
    print(f"epoch {epoch:02d}/{epochs} train={train_loss:.5f} val={val_loss:.5f} "
          f"{time.time()-t0:.1f}s ({train_ds.size/max(time.time()-t0,1e-9):.0f} pos/s)", flush=True)

    if val_loss < best_val:
        best_val = val_loss
        qnet = quantize_weights(model.state_dict())
        nnue_format.write_network(qnet, best_path)
        print(f"  saved {best_path} val={val_loss:.5f}", flush=True)

assert os.path.exists(best_path)
print(f"done: {os.path.getsize(best_path):,} bytes")
